"""Export mount-local presentation deltas, sampled on replicated action progress."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[1]
d=json.loads((OUT/'presentation.json').read_text())
rows=['#pragma once','#include "CoreMinimal.h"',
      '// Generated by SourceAssets/KukriThirdPersonCompletion20261029/export_presentation.py.',
      '// Native mount-local deltas, cm. Presentation only; no collision or gameplay notifies.',
      'namespace FPSBodyKukriPresentationData','{',
      'struct FKey { float X,Y,Z,QX,QY,QZ,QW; };']
for label,takes in d.items():
    for take,data in takes.items():
        for side,keys in data['blades'].items():
            name=label.capitalize()+take+side.upper();rows.append('inline constexpr FKey '+name+'[]={')
            for k in keys:rows.append('    {'+','.join(f'{v:.7f}f' for v in k)+'},')
            rows.append('};')
rows+=['template<int32 N> inline FTransform Sample(const FKey (&Keys)[N],float Progress)',
       '{','    const float X=FMath::Clamp(Progress,0.f,1.f)*(N-1);',
       '    const int32 I=FMath::Min(int32(X),N-2);const auto& A=Keys[I];const auto& B=Keys[I+1];',
       '    return FTransform(FQuat::Slerp(FQuat(A.QX,A.QY,A.QZ,A.QW),FQuat(B.QX,B.QY,B.QZ,B.QW),X-I).GetNormalized(),',
       '        FMath::Lerp(FVector(A.X,A.Y,A.Z),FVector(B.X,B.Y,B.Z),X-I));','}',
       'inline FTransform Equip(bool Kaitlin,bool Dual,int32 Side,float Progress)','{',
       '    if(Dual&&Side==1)return Kaitlin?Sample(KaitlinDualEquipL,Progress):Sample(JasonDualEquipL,Progress);',
       '    if(Dual)return Kaitlin?Sample(KaitlinDualEquipR,Progress):Sample(JasonDualEquipR,Progress);',
       '    return Kaitlin?Sample(KaitlinEquipR,Progress):Sample(JasonEquipR,Progress);','}',
       'inline FTransform Uppercut(bool Kaitlin,float Progress)','{',
       '    return Kaitlin?Sample(KaitlinUppercutL,Progress):Sample(JasonUppercutL,Progress);','}','}']
(ROOT/'Source/FPSGAME/Characters/FPSBodyKukriPresentationData.h').write_text('\n'.join(rows)+'\n')
print('KUKRI_PRESENTATION_EXPORTED',sum(len(v['blades']) for x in d.values() for v in x.values()))
